import React from 'react';
import './PaymentPartners.css';

const PaymentPartners = () => {
    const partners = [
        {
            name: 'eSewa',
            logo: 'https://upload.wikimedia.org/wikipedia/commons/f/ff/Esewa_logo.webp',
            url: 'https://esewa.com.np'
        },
        {
            name: 'Khalti',
            logo: 'https://blog.khalti.com/wp-content/uploads/2021/01/khalti-logo.png',
            url: 'https://khalti.com'
        },
        {
            name: 'ConnectIPS',
            logo: 'https://www.connectips.com/images/connectips-logo.png',
            url: 'https://www.connectips.com'
        }
    ];

    return (
        <section className="payment-partners-section">
            <div className="container">
                <h2 className="section-title">Digital Payment Partners</h2>
                <div className="partners-grid">
                    {partners.map((partner, index) => (
                        <a 
                            key={index} 
                            href={partner.url} 
                            target="_blank" 
                            rel="noopener noreferrer" 
                            className="partner-card"
                        >
                            <div className="logo-wrapper">
                                <img src={partner.logo} alt={partner.name} title={partner.name} />
                            </div>
                        </a>
                    ))}
                </div>
            </div>
        </section>
    );
};

export default PaymentPartners;
